// TerminalCursor.jsx
import React, { useEffect } from 'react';
import styles from './TerminalCursor.module.css';

const TerminalCursor = () => {
  useEffect(() => {
    // Add terminal-style cursor to entire page
    document.body.classList.add(styles.terminalCursor);
    
    // Function to check if element has cyan background or text
    const isCyanElement = (element) => {
      const computedStyle = window.getComputedStyle(element);
      const bgColor = computedStyle.backgroundColor;
      const color = computedStyle.color;
      
      // Check if color is cyan (rgb(0, 255, 255) or similar)
      const isCyan = (rgbString) => {
        const match = rgbString.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
        if (match) {
          const r = parseInt(match[1]);
          const g = parseInt(match[2]);
          const b = parseInt(match[3]);
          // Cyan is typically high green and blue, low red
          return g > 200 && b > 200 && r < 100;
        }
        return false;
      };
      
      return isCyan(bgColor) || isCyan(color);
    };
    
    // Function to update cursor based on element under cursor
    const updateCursor = (e) => {
      const target = e.target;
      if (isCyanElement(target)) {
        target.style.cursor = "url('data:image/svg+xml;utf8,<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\"><rect x=\"1\" y=\"1\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"black\" stroke-width=\"3\" /><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" fill=\"white\" opacity=\"0.9\" /><text x=\"12\" y=\"17\" font-family=\"monospace\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\">_</text></svg>') 12 12, auto";
      } else {
        target.style.cursor = "";
      }
    };
    
    // Add mousemove listener
    document.addEventListener('mousemove', updateCursor);
    
    return () => {
      document.body.classList.remove(styles.terminalCursor);
      document.removeEventListener('mousemove', updateCursor);
    };
  }, []);

  return null;
};

export default TerminalCursor;
